module histories::generic_app;import "./model.nex" as model;
server fn main()->i64 !{task,fs}{let box:model::Box<file>=model::transit(model::open());assert(unwrap(file_read(box.value,6))==utf8_bytes("abcdef"));assert(file_close(box.value));return 42;}

client fn client_value()->i64{return 42;}
test fn pure_answer()->unit{assert(42>41);}

